<div class="d-flex flex-wrap justify-content-between align-items-center mb-4"><div><h1 class="h3 mb-1">Calendario</h1><p class="text-secondary mb-0"><?= e($startLabel) ?><?= $startLabel!==$endLabel?' – '.e($endLabel):'' ?></p></div><a class="btn btn-primary" href="/app/calendario/nuovo">＋ Nuovo evento</a></div>
<div class="d-flex flex-wrap gap-2 mb-3"><?php foreach(['giorno'=>'Giorno','settimana'=>'Settimana','mese'=>'Mese'] as $key=>$label): ?><a class="btn btn-sm <?= $vista===$key?'btn-primary':'btn-outline-primary' ?>" href="/app/calendario?vista=<?= e($key) ?>&data=<?= e($data) ?>"><?= e($label) ?></a><?php endforeach ?><form class="d-flex gap-2 ms-md-auto"><input type="hidden" name="vista" value="<?= e($vista) ?>"><input class="form-control form-control-sm" type="date" name="data" value="<?= e($data) ?>"><button class="btn btn-sm btn-outline-secondary">Vai</button></form></div>
<div class="card border-0 shadow-sm"><div class="table-responsive"><table class="table table-hover align-middle mb-0"><thead class="table-light"><tr><th>Data e ora</th><th>Attività</th><th>Tipo</th><th>Assegnato a</th><th></th></tr></thead><tbody><?php if(!$records): ?><tr><td colspan="5" class="text-center text-secondary py-5">Nessun evento nel periodo selezionato.</td></tr><?php endif ?><?php foreach($records as $event): ?><tr><td><?= e(date('d/m/Y H:i',strtotime($event['inizio']))) ?></td><td><?= e($event['titolo']) ?></td><td><span class="badge text-bg-light"><?= e(ucfirst($event['tipo'])) ?></span></td><td><?= e($event['operatore']?:'—') ?></td><td class="text-end"><a class="btn btn-sm btn-outline-primary" href="/app/calendario/<?= (int)$event['id'] ?>">Apri</a></td></tr><?php endforeach ?></tbody></table></div></div>
